using System.Net.Http.Json;
using sv_a63a6c9732f7485d9c6a4ec5f8794ce3.Client.Models;

namespace sv_a63a6c9732f7485d9c6a4ec5f8794ce3.Client.Services;

/// <summary>
/// HTTP-based implementation of <see cref="IShipmentService"/> used when
/// running in the WebAssembly render mode.
/// </summary>
public class ShipmentServiceClient(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var encoded = Uri.EscapeDataString(trackingNumber);
        var response = await http.GetAsync($"api/shipments/{encoded}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

